<script setup lang="ts">
import {ref,onMounted} from 'vue'
const props=defineProps<{space:string;request:(path:string,body?:any,method?:string)=>Promise<any>}>()
const rows=ref<any[]>([]),page=ref(1),count=ref(0),busy=ref(false),error=ref(''),message=ref('')
const form=ref({username:'',email:'',role:'setter'})
const base=()=>`workspaces/${props.space}/invitations/`
async function load(){try{const data=await props.request(base()+`?page=${page.value}`);rows.value=data.results;count.value=data.count}catch(e:any){error.value=e.message}}
async function create(){busy.value=true;error.value='';message.value='';try{const result=await props.request(base(),form.value);form.value={username:'',email:'',role:'setter'};page.value=1;await load();message.value=result.mail_sent?'Invitation envoyée.':'Invitation enregistrée, mais e-mail non envoyé. Vous pouvez réessayer.'}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function action(row:any,action:string){busy.value=true;error.value='';message.value='';try{const result=await props.request(base()+row.id+'/',{action});message.value=action==='revoke'?'Invitation révoquée.':result.mail_sent?'Nouveau lien envoyé ; le précédent est invalidé.':'Envoi échoué ; réessayez.';await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
const labels:Record<string,string>={pending:'En attente',accepted:'Acceptée',revoked:'Révoquée',expired:'Expirée'}
onMounted(load)
</script>
<template><section class="card" style="padding:24px;margin-top:24px"><h2>Invitations à {{space}}</h2><p>Pour un nouveau compte : le destinataire choisira son mot de passe. Aucun accès avant acceptation.</p><p v-if="error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p><form @submit.prevent="create"><label>Identifiant<input v-model="form.username" required maxlength="150"></label><label>E-mail<input v-model="form.email" type="email" required maxlength="254"></label><label>Rôle<select v-model="form.role"><option value="setter">Setter</option><option value="administrator">Administrateur</option><option v-if="space==='assurance'" value="advisor">Conseiller</option><option v-else value="client">Client</option></select></label><button class="primary" :disabled="busy">Envoyer l’invitation</button></form><div class="table-scroll"><table><thead><tr><th>Identifiant / e-mail</th><th>Rôle</th><th>État</th><th>Actions</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.username}} · {{row.email}}</td><td>{{row.role}}</td><td>{{labels[row.status]}}</td><td v-if="['pending','expired'].includes(row.status)"><button class="secondary" :disabled="busy" @click="action(row,'resend')">Renvoyer</button><button class="secondary" :disabled="busy" @click="action(row,'revoke')">Révoquer</button></td><td v-else>Clôturée</td></tr></tbody></table></div><button class="secondary" :disabled="busy||page===1" @click="page--;load()">Précédent</button><span> Page {{page}} · {{count}} invitation(s) </span><button class="secondary" :disabled="busy||page*25>=count" @click="page++;load()">Suivant</button></section></template>
